    emit,
  } = opts;

  // ── Max-turns retry ───────────────────────────────────────────────────────
  if (
    result.terminal_status === "blocked" &&
    typeof result.blocked_reason === "string" &&
    result.blocked_reason.startsWith("max_turns")
  ) {
    const branch = taskBranchName(featureId, taskId);
    const relPath = `docs/features/${featureId}/tasks/${taskId}.yaml`;
    const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
    if (branchTask) {
      const retriedCount = (branchTask.log ?? []).filter((e) => e.action === "retried").length;
      if (retriedCount < EXECUTOR_MAX_RETRIES) {
        const mutateErr = mutateTaskYamlDirect({
          workspaceRoot, featureId, taskId, taskBranch, status: "ready",
          logEntry: {
            action: "retried", by: gitAuthorEmail,
            note: `Max-turns block reset to ready (attempt ${retriedCount + 1} of ${EXECUTOR_MAX_RETRIES}).`,
          },
          gitAuthorEmail, gitAuthorName, sshKeyPath,
          commitMessage: `chore(${taskId}): retried — max-turns reset (${retriedCount + 1}/${EXECUTOR_MAX_RETRIES})`,
        });
        if (mutateErr) {
          emit({ type: "retry_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
        } else {
          emit({ type: "task_retried", task_id: taskId, feature_id: featureId, attempt: retriedCount + 1, max: EXECUTOR_MAX_RETRIES });
          return;
        }
      } else {
        emit({ type: "task_max_retries_exceeded", task_id: taskId, feature_id: featureId, max: EXECUTOR_MAX_RETRIES });
      }
    }
  }

  // pr_url from result.json — set by executor when it opened a PR.
  // Present on any terminal_status when commits were pushed and a PR was opened.
  const prUrl = result.pr_url;

  if (result.terminal_status === "in_review") {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
      const prMatch = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(prUrl);
      if (prMatch && githubToken) {
        const [, owner, repo, prNumber] = prMatch;
        // wipTitle is set only after a successful promote, so the title PATCH
        // only runs when the draft→ready transition actually completed.
        let wipTitle: string | undefined;
        try {
          // REST PATCH draft:false is silently ignored by GitHub — use GraphQL instead.
          const prData = curlJson([
            "-s", "--fail",
            "-H", `Authorization: token ${githubToken}`,
            "-H", "Accept: application/vnd.github+json",
            `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
          ]) as { node_id?: string; title?: string };
          const nodeId = prData.node_id;
          if (!nodeId) throw new Error("PR node_id missing from REST response");
          curlJson([
            "-s", "--fail", "-X", "POST",
            "-H", `Authorization: token ${githubToken}`,
            "-H", "Content-Type: application/json",
            "-d", JSON.stringify({
              query: `mutation { markPullRequestReadyForReview(input: { pullRequestId: "${nodeId}" }) { pullRequest { isDraft } } }`,
            }),
            "https://api.github.com/graphql",
          ]);
          // Capture the WIP title after promote succeeds so cleanup runs in its own try/catch.
          if (prData.title?.startsWith("[WIP]")) wipTitle = prData.title;
        } catch (e) {
          emit({ type: "task_pr_promote_failed", task_id: taskId, feature_id: featureId, details: String(e) });
        }
        // Clean up WIP title/body set by the recovery routine when agent crashed.
        // Runs independently of promote so a PATCH failure doesn't misattribute as promote failure.
        if (wipTitle !== undefined) {
          try {
            // Preserve the conventional-commit type embedded in the WIP title (feat/fix/chore/…).
            const prType = /^\[WIP\] (\w+)\(/.exec(wipTitle)?.[1] ?? "feat";
            const cleanTitle = `${prType}(${featureId}/${taskId}): ${taskTitle}`;
            const cleanBody = [
              `## ${taskTitle}`,
              "",
              `**Feature:** ${featureId}`,
              `**Task:** ${taskId}`,
              `**Branch:** \`${taskBranch}\``,
            ].join("\n");
            curlJson([
              "-s", "--fail", "-X", "PATCH",
              "-H", `Authorization: token ${githubToken}`,
              "-H", "Accept: application/vnd.github+json",
              "-H", "Content-Type: application/json",
              "-d", JSON.stringify({ title: cleanTitle, body: cleanBody }),
              `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
            ]);
            emit({ type: "task_pr_title_updated", task_id: taskId, feature_id: featureId, pr_url: prUrl });
          } catch (e) {
            emit({ type: "task_pr_title_update_failed", task_id: taskId, feature_id: featureId, details: String(e) });
          }
        }
      }
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const runCompletedEntry: Omit<TaskLogEntry, "at"> = {
      action: "run_completed",
      by: gitAuthorEmail,
      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: runCompletedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });

    if (notifier) {
      try {
        await notifier.notify({ type: "in_review", featureId, taskId, taskTitle, prUrl });
      } catch (e) {
        emit({ type: "task_notification_failed", task_id: taskId, feature_id: featureId, event: "in_review", error: String(e) });
      }
    }
  } else {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const blockedEntry: Omit<TaskLogEntry, "at"> = {
      action: "blocked",
      by: gitAuthorEmail,
      note: result.blocked_reason ?? "executor returned non-in_review status",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: blockedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });

    if (notifier) {
      try {
        await notifier.notify({ type: "blocked", featureId, taskId, taskTitle, prUrl, blockedReason: result.blocked_reason ?? undefined });
      } catch (e) {
        emit({ type: "task_notification_failed", task_id: taskId, feature_id: featureId, event: "blocked", error: String(e) });
      }
    }
  }
}

