      type: "escalation_mutate_failed",
      task_id: taskId,
      feature_id: featureId,
      details: mutateErr,
    });
    return;
  }

  emit({
    type: "task_escalated",
    task_id: taskId,
    feature_id: featureId,
    notes,
  });
}

