127	function resolveTaskContext(
128	  workspaceLocalPath: string,
129	  featureId: string,
130	  task: Task,
131	): TaskContext {
132	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
133	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
134	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
135	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
136	
137	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
138	  let taskModelOverrides = {};
139	  try {
140	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
141	  } catch { /* non-fatal */ }
142	
143	  const implementationModel = resolveModel(
144	    workspaceModelPolicy,
145	    taskModelOverrides,
146	    "implementation",
147	    task.id,
148	  );
149	
150	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
