208	async function main(): Promise<number> {
209	  let agentYamlPath: string;
210	  let workflowLocalPath: string;
211	  let workspacesRoot: string;
212	  let gitAuthorEmail: string;
213	
214	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
215	  const bootstrapEmit = (event: Record<string, unknown>) => {
216	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
217	  };
218	
219	  try {
220	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
221	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
222	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
223	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
224	  } catch (e) {
225	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
226	    return 4;
227	  }
228	
229	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
230	
231	  const sshResolution = resolveSSHKey(process.env);
232	  const { sshKeyPath } = sshResolution;
233	  if (!sshKeyPath) {
234	    console.error("SSH_PRIVATE_KEY is not set — cannot perform git operations over SSH. Exiting.");
235	    return 1;
236	  }
237	
238	  // ── Create the runtime profile ────────────────────────────────────────────────
239	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
240	  // new infra is added without core changes.
241	  //   local-subprocess (default) — executor + in-process broker in one container
242	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
243	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
244	
245	  // Resolved once at startup so buildAndSubmitExecutor can reuse the same path.
246	  // local-docker ignores this (ClaudeDockerRunAdapter selects the binary differently).
247	  const resolvedExecutorBinPath: string | undefined =
248	    runtimeProfile !== "local-docker"
249	      ? resolveExecutorBin(process.env.EXECUTOR_TYPE ?? "claude", {
250	          hermesModel: process.env.HERMES_INFERENCE_MODEL,
251	          hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
252	          deepseekApiKey: process.env.DEEPSEEK_API_KEY,
253	          ragMcpUrl: process.env.MCP_RAG_URL,
254	          hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
255	        })
256	      : undefined;
257	
258	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
259	    runtimeProfile === "local-docker"
260	      ? createLocalDockerProfile({
261	          gitAuthorEmail,
262	          gitAuthorName,
263	          sshKeyPath,
264	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
265	        })
266	      : (() => {
267	          const executorType = process.env.EXECUTOR_TYPE ?? "claude";
268	          const factoryConfig = {
269	            hermesModel: process.env.HERMES_INFERENCE_MODEL,
270	            hermesProvider: process.env.HERMES_INFERENCE_PROVIDER,
271	            deepseekApiKey: process.env.DEEPSEEK_API_KEY,
272	            ragMcpUrl: process.env.MCP_RAG_URL,
273	            hermesMaxTurns: process.env.HERMES_MAX_TURNS ? parseInt(process.env.HERMES_MAX_TURNS, 10) : undefined,
274	          };
275	          return createLocalSubprocessProfile({
276	            gitAuthorEmail,
277	            gitAuthorName,
278	            sshKeyPath,
279	            executor: {
280	              executorBinPath: resolvedExecutorBinPath,
281	              extraEnv: resolveExecutorEnv(executorType, factoryConfig),
282	            },
283	          });
284	        })();
285	
286	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
287	  const brokerPort = await ports.broker.start();
288	
289	  const emit = makeEmit(ports);
290	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
291	
292	  const bootstrapResult = await runBootstrap({ agentYamlPath });
293	
294	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
295	
296	  const config = bootstrapResult.config!;
297	  const githubToken = process.env.GITHUB_TOKEN ?? "";
298	  if (!githubToken) emit({ type: "warn_no_github_token" });
299	
300	  // Local counter for local-docker mode — tracks how many executor containers are
301	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
302	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
303	  let dockerInFlight = 0;
304	  // Tracks in-flight rebase executors by "featureId:taskId" key. Prevents duplicate
305	  // dispatch when the PR poll fires while a rebase executor is still running (docker
306	  // mode has no registrySize() guard equivalent for rebase tasks).
307	  const rebaseInFlight = new Set<string>();
308	  let cycleCount = 0;
309	  const stateInvariantCheckInterval = parseInt(
310	    process.env.STATE_INVARIANT_CHECK_INTERVAL ?? "5",
311	    10,
312	  );
313	  const featureReviewInterval = parseInt(
314	    process.env.FEATURE_REVIEW_INTERVAL ?? "20",
315	    10,
316	  );
