419	  // ── Sync workspaces + feature branch lifecycle ────────────────────────────
420	  async function syncWorkspaces(): Promise<{
421	    haltedUrls: Set<string>;
422	    failedFeatureBranchMap: Map<string, Set<string>>;
423	  }> {
424	    // Skip impl repo pulls while an executor is in-flight.
425	    // syncRepo does `checkout <baseBranch> && reset --hard origin/<baseBranch>`,
426	    // which would switch the shared working tree away from the task branch and
427	    // wipe any uncommitted edits the executor made in the impl repo.
428	    const inFlightCount = ports.broker.inFlightCount?.() ?? 0;
429	
430	    const pullResults = pullWorkspaces({
431	      watchUrls: config.watches,
432	      sshKeyPath,
433	      workspacesRoot,
434	      workflowUrl: process.env.WORKFLOW_URL,
435	      workflowLocalPath,
436	      emit,
437	      skipImplRepoPull: inFlightCount > 0,
438	    });
439	
440	    const haltedUrls = new Set(
441	      pullResults
442	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
443	        .map((r) => r.url),
444	    );
445	
446	    const failedFeatureBranchMap = new Map<string, Set<string>>();
447	    for (const watchUrl of config.watches) {
448	      if (haltedUrls.has(watchUrl)) continue;
449	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
450	      if (!existsSync(workspaceLocalPath)) continue;
451	      try {
452	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
453	        const failed = runFeatureBranchLifecycle({
454	          workspaceRoot: workspaceLocalPath,
455	          baseBranch: mgmtCoords.baseBranch,
456	          gitAuthorEmail,
457	          gitAuthorName,
458	          sshKeyPath,
459	          githubToken: githubToken || undefined,
460	          repoOwner: mgmtCoords.owner,
461	          repoName: mgmtCoords.repo,
462	          slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
463	          emit,
464	        });
465	        if (failed.size > 0) {
466	          failedFeatureBranchMap.set(workspaceLocalPath, failed);
467	          emit({ type: "feature_branch_lifecycle_blocked", workspace: watchUrl, failed_features: [...failed] });
468	        }
469	      } catch (e) {
470	        emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
471	      }
472	    }
473	
474	    return { haltedUrls, failedFeatureBranchMap };
475	  }
476	
477	  // ── Claim step: scan ready tasks, claim + spawn executor ─────────────────
478	  async function claimStep(
479	    haltedUrls: Set<string>,
480	    failedFeatureBranchMap: Map<string, Set<string>>,
481	  ): Promise<{ outcome: CycleOutcome; pulledWorkspaceRoots: string[] }> {
482	    const pulledWorkspaceRoots: string[] = [];
483	
484	    for (const watchUrl of config.watches) {
485	      if (haltedUrls.has(watchUrl)) continue;
486	
487	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
488	      pulledWorkspaceRoots.push(workspaceLocalPath);
489	
490	      if (!existsSync(workspaceLocalPath)) {
491	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
492	        continue;
493	      }
494	
495	      let eligibleTasks;
496	      try {
497	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
498	      } catch (e) {
499	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
500	        continue;
501	      }
502	
503	      if (eligibleTasks.length === 0) {
504	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
505	        continue;
506	      }
507	
508	      for (const { task, featureId } of eligibleTasks) {
509	        if (failedFeatureBranchMap.get(workspaceLocalPath)?.has(featureId)) {
510	          emit({ type: "task_skipped_feature_branch_failed", task_id: task.id, feature_id: featureId });
511	          continue;
512	        }
513	
514	        const claimResult = await claimTask({
515	          workspaceRoot: workspaceLocalPath,
516	          taskId: task.id,
517	          featureId,
518	          gitAuthorEmail,
519	          gitAuthorName,
520	          sshKeyPath,
521	          jitterMaxSeconds: config.jitter_max_seconds,
522	          // Task branches are seeded from and target the feature branch, not
523	          // the base branch — task PRs collect into the feature branch before
524	          // the Handoff Trigger merges the feature branch into the base.
525	          baseBranch: featureBranchName(featureId),
526	        });
527	
528	        const taskBranch = taskBranchName(featureId, task.id);
529	
530	        if (!claimResult.won) {
531	          if (claimResult.reason !== "branch_blocked_recovery") {
532	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
533	            continue;
534	          }
535	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
536	        } else {
537	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
538	        }
539	
540	        // ── Open management-repo PR ─────────────────────────────────────────
541	        if (githubToken) {
542	          try {
543	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
544	            await openWorkspacePr({
545	              workspaceRoot: workspaceLocalPath,
546	              featureId,
547	              taskId: task.id,
548	              branch: taskBranch,
549	              // Task PRs target the feature branch so all task changes collect
550	              // there before the Handoff Trigger merges to the base branch (T8).
551	              baseBranch: featureBranchName(featureId),
552	              githubToken,
553	              repoOwner: mgmtCoords.owner,
554	              repoName: mgmtCoords.repo,
555	              gitAuthorEmail,
556	              gitAuthorName,
557	              sshKeyPath,
558	            });
559	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
560	          } catch (e) {
561	            const stderr = (e as { stderr?: Buffer | string }).stderr;
562	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
563	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
564	          }
565	        }
566	
567	        // ── Resolve model + task repo ───────────────────────────────────────
568	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
569	          resolveTaskContext(workspaceLocalPath, featureId, task);
570	
571	        // ── RAG pre-flight ──────────────────────────────────────────────────
572	        const mcpRagUrl = process.env.MCP_RAG_URL;
573	        const workspaceYaml = parseYaml(
574	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
575	        ) as { workspace_id: string };
576	        const ragQuery = `${task.title} ${featureId}`;
577	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
578	
579	        try {
580	          writeRagPreFlight(
581	            workspaceLocalPath,
582	            featureId,
583	            task.id,
584	            taskBranch,
585	            gitAuthorEmail,
586	            gitAuthorName,
587	            sshKeyPath,
588	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
589	          );
590	        } catch (e) {
591	          const details = String(e);
592	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
593	          mutateTaskYaml({
594	            workspaceRoot: workspaceLocalPath,
595	            featureId,
596	            taskId: task.id,
597	            taskBranch,
598	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
599	            gitAuthorEmail,
600	            gitAuthorName,
601	            sshKeyPath,
602	          });
603	          continue;
604	        }
605	
606	
607	        // ── Submit executor (async — T6) ────────────────────────────────────
608	        const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
609	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
610	        const execHandle = await buildAndSubmitExecutor({
611	          task, featureId, workspaceId: workspaceYaml.workspace_id,
612	          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
613	          mgmtRepoUrl: mgmtCoords.repoUrl, implementationModel,
614	          resultPath, workspaceLocalPath,
615	        });
616	
617	        // Persist handle to task YAML for broker crash-recovery reconciliation.
618	        try {
619	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
620	        } catch (e) {
621	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
622	        }
623	
624	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
625	        if (runtimeProfile === "local-docker") dockerInFlight++;
626	        return { outcome: "ran_task", pulledWorkspaceRoots };
627	      }
628	    }
629	    return { outcome: "idle", pulledWorkspaceRoots };
630	  }
631	
632	  // ── Fix step: scan change_requested tasks, claim + spawn fix executor ─────
633	  async function fixStep(haltedUrls: Set<string>): Promise<CycleOutcome> {
634	    for (const watchUrl of config.watches) {
635	      if (haltedUrls.has(watchUrl)) continue;
636	
637	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
638	      if (!existsSync(workspaceLocalPath)) continue;
639	
640	      let fixableTasks;
641	      try {
642	        fixableTasks = findFixableTasks(config, workspaceLocalPath);
643	      } catch (e) {
644	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
645	        continue;
646	      }
647	
648	      for (const { task, featureId } of fixableTasks) {
649	        const taskBranch = taskBranchName(featureId, task.id);
650	        const claimResult = await claimFixTask({
651	          workspaceRoot: workspaceLocalPath,
652	          taskId: task.id,
653	          featureId,
654	          gitAuthorEmail,
655	          gitAuthorName,
656	          sshKeyPath,
657	          jitterMaxSeconds: config.jitter_max_seconds,
658	        });
659	
660	        if (!claimResult.won) {
661	          emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason, details: claimResult.details });
662	          continue;
663	        }
664	
665	        emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
666	
667	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
668	        const fixWsYaml = parseYaml(
669	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
670	        ) as { workspace_id: string };
671	
672	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
673	        const prUrl = extractPrUrlFromTask(task);
674	        // Find the most recent reviewer_complete log entry and pull its
675	        // review_url out. The orchestrator persists review_url on
676	        // change_requested mutations (dispatch-review-result.ts) so the fix
677	        // agent can target THIS specific review's inline comments rather
678	        // than fetching "all unresolved threads on the PR" (lossy across
679	        // multiple review cycles).
680	        const lastReviewerComplete = [...task.log]
681	          .reverse()
682	          .find((e) => e.action === "reviewer_complete");
683	        const reviewUrl =
684	          typeof lastReviewerComplete?.review_url === "string"
685	            ? lastReviewerComplete.review_url
686	            : undefined;
687	        emit({ type: "fix_executor_dispatch_started", task_id: task.id, feature_id: featureId, pr_url: prUrl, review_url: reviewUrl });
688	        const fixMgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
689	        const fixHandle = await buildAndSubmitExecutor({
690	          task, featureId, workspaceId: fixWsYaml.workspace_id,
691	          taskRepoUrl, taskBranch, taskBaseBranch: featureBranchName(featureId), taskRepoBaseBranch: taskBaseBranch,
692	          mgmtRepoUrl: fixMgmtCoords.repoUrl, implementationModel,
693	          resultPath, workspaceLocalPath,
694	          kind: "fix",
695	          prUrl: prUrl ?? undefined,
696	          reviewUrl,
697	        });
698	        emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
699	        if (runtimeProfile === "local-docker") dockerInFlight++;
700	        return "ran_task";
701	      }
702	    }
703	    return "idle";
704	  }
705	
706	  // ── PR poll step (5a): rebase conflicted PRs + handle merged PRs ──────────
707	  // Runs inside dispatchBlock so the subprocess guard prevents it from running
708	  // while an executor shares the container filesystem.
709	  async function prPollStep(pulledWorkspaceRoots: string[]): Promise<CycleOutcome> {
710	    let outcome: CycleOutcome = "idle";
711	    let prResults: PrStatusResult[] = [];
712	    try {
713	      ({ prResults } = await checkInReviewPrs({
714	        workspaceRoots: pulledWorkspaceRoots,
715	        githubToken,
716	        emit,
717	      }));
718	    } catch (e) {
719	      emit({ type: "in_review_poll_error", details: String(e) });
720	    }
721	
722	    for (const wsRoot of pulledWorkspaceRoots) {
723	      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
724	      for (const pr of wsResults.filter((r) => r.mergeable === false)) {
725	        const rebaseKey = `${pr.featureId}:${pr.taskId}`;
726	        if (rebaseInFlight.has(rebaseKey)) {
727	          emit({ type: "rebase_skipped_in_flight", task_id: pr.taskId, feature_id: pr.featureId });
728	          continue;
729	        }
730	        const rebaseTaskBranch = taskBranchName(pr.featureId, pr.taskId);
731	        const claimResult = claimRebase({
732	          workspaceRoot: wsRoot,
733	          featureId: pr.featureId,
734	          taskId: pr.taskId,
735	          taskBranch: rebaseTaskBranch,
736	          implBaseBranch: featureBranchName(pr.featureId),
737	          gitAuthorEmail,
738	          gitAuthorName,
739	          sshKeyPath,
740	          emit,
741	        });
742	        if (claimResult === "claim_lost") continue;
743	
744	        let rebaseTask: Task;
745	        try {
746	          rebaseTask = parseYaml(
747	            readFileSync(taskYamlAbsPath(wsRoot, pr.featureId, pr.taskId), "utf-8"),
748	          ) as Task;
749	        } catch (e) {
750	          emit({ type: "rebase_dispatch_read_error", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
751	          continue;
752	        }
753	        const { taskRepoUrl: rebaseImplUrl, taskBaseBranch: rebaseImplBase, implementationModel: rebaseModel } =
754	          resolveTaskContext(wsRoot, pr.featureId, rebaseTask);
755	        const rebaseMgmtCoords = parseManagementRepoCoords(wsRoot);
756	        const rebaseWsYaml = parseYaml(
757	          readFileSync(workspaceYamlPath(wsRoot), "utf-8"),
758	        ) as { workspace_id: string };
759	        // Result path uniqueness: same task can be re-dispatched after a failed
760	        // rebase, so suffix the path with a random slice (not the broker handle,
761	        // which is generated inside buildAndSubmitExecutor).
762	        const rebaseResultPath = join(tmpdir(), `rebase-result-${pr.taskId}-${randomUUID().slice(0, 8)}.json`);
763	        try {
764	          const rebaseHandle = await buildAndSubmitExecutor({
765	            task: rebaseTask,
766	            featureId: pr.featureId,
767	            workspaceId: rebaseWsYaml.workspace_id,
768	            taskRepoUrl: rebaseImplUrl,
769	            taskBranch: rebaseTaskBranch,
770	            // Rebase PR base is the feature branch (impl task PRs target it).
771	            taskBaseBranch: featureBranchName(pr.featureId),
772	            taskRepoBaseBranch: rebaseImplBase,
773	            mgmtRepoUrl: rebaseMgmtCoords.repoUrl,
774	            implementationModel: rebaseModel,
775	            resultPath: rebaseResultPath,
776	            workspaceLocalPath: wsRoot,
777	            kind: "rebase",
778	            prUrl: extractPrUrlFromTask(rebaseTask) ?? undefined,
779	          });
780	          rebaseInFlight.add(rebaseKey);
781	          outcome = "ran_task";
782	          emit({ type: "rebase_dispatched", task_id: pr.taskId, feature_id: pr.featureId, handle: rebaseHandle });
783	          if (runtimeProfile === "local-docker") dockerInFlight++;
784	        } catch (e) {
785	          emit({ type: "rebase_dispatch_failed", task_id: pr.taskId, feature_id: pr.featureId, details: String(e) });
786	        }
787	      }
788	    }
789	
790	    for (const wsRoot of pulledWorkspaceRoots) {
791	      const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
792	      if (wsResults.some((r) => r.merged === true)) {
793	        outcome = "ran_task";
794	        const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
795	        const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
796	        const mgmtCoords = parseManagementRepoCoords(wsRoot);
797	        try {
798	          await handleMergedPrs({
799	            prResults: wsResults,
800	            workspaceRoot: wsRoot,
801	            mgmtRepoOwner: mgmtCoords.owner,
802	            mgmtRepoName: mgmtCoords.repo,
803	            mgmtBaseBranch: mgmtCoords.baseBranch,
804	            githubToken,
805	            gitAuthorEmail,
806	            gitAuthorName,
807	            sshKeyPath,
808	            notifier: taskNotifier,
809	            emit,
810	            invokeClaudeForResolution: makeConflictResolver(conflictModel),
811	          });
812	        } catch (e) {
813	          emit({ type: "handle_merged_prs_error", workspace: wsRoot, details: String(e) });
814	        }
815	      }
816	    }
817	
818	    return outcome;
819	  }
820	
821	  // ── Reviewer step (5b): dispatch reviewer agents ──────────────────────────
822	  // Only runs when 5a found no conflicts or merges this cycle.
823	  async function reviewerStep(haltedUrls: Set<string>): Promise<CycleOutcome> {
824	    for (const watchUrl of config.watches) {
825	      if (haltedUrls.has(watchUrl)) continue;
826	
827	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
828	      if (!existsSync(workspaceLocalPath)) continue;
829	
830	      let reviewableTasks;
831	      try {
832	        reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
833	      } catch (e) {
834	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
835	        continue;
836	      }
837	
838	      for (const { task, featureId } of reviewableTasks) {
839	        const taskBranch = taskBranchName(featureId, task.id);
840	        const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
841	        const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
842	        const revWsYaml = parseYaml(
843	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
844	        ) as { workspace_id: string };
845	        let reviewModelOverrides = {};
846	        try {
847	          const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
848	          reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
849	        } catch { /* non-fatal */ }
850	        const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);
851	
852	        const reviewerMgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
853	        const dispatchResult = await dispatchReviewer({
854	          workspaceRoot: workspaceLocalPath,
855	          featureId,
856	          taskId: task.id,
857	          taskBranch,
858	          implRepoRoot: taskRepoRoot,
859	          implRepoUrl: taskRepoUrl,
860	          mgmtRepoUrl: reviewerMgmtCoords.repoUrl,
861	          gitAuthorEmail,
862	          gitAuthorName,
863	          sshKeyPath,
864	          workflowLocalPath,
865	          maxTurns: config.budget.max_iterations,
866	          maxTokens: config.budget.max_tokens_per_task,
867	          logSinkEnabled: config.log_sink.enabled,
868	          reviewerModel,
869	          workspaceId: revWsYaml.workspace_id,
870	          broker: ports.broker,
871	          callbackUrl: ports.broker.getCallbackUrl() ?? "",
872	          emit,
873	        });
874	
875	        if (dispatchResult === "dispatched") {
876	          if (runtimeProfile === "local-docker") dockerInFlight++;
877	          return "ran_task";
878	        }
879	      }
880	    }
881	    return "idle";
882	  }
883	
884	  // ── Feature Done Watcher ──────────────────────────────────────────────────
885	  async function featureDoneStep(pulledWorkspaceRoots: string[]): Promise<void> {
886	    for (const wsRoot of pulledWorkspaceRoots) {
887	      try {
888	        await handleFeatureDone({
889	          workspaceRoot: wsRoot,
890	          githubToken,
891	          gitAuthorEmail,
892	          gitAuthorName,
893	          sshKeyPath,
894	          emit,
895	        });
896	      } catch (e) {
897	        emit({ type: "feature_done_watcher_error", workspace: wsRoot, details: String(e) });
898	      }
899	    }
900	  }
901	
902	  // ── Feature-Tasks-Done checker (every cycle) ──────────────────────────────
903	  async function checkFeatureTasksDoneStep(pulledWorkspaceRoots: string[]): Promise<void> {
904	    for (const wsRoot of pulledWorkspaceRoots) {
905	      try {
906	        await checkFeatureTasksDone({
907	          workspaceRoot: wsRoot,
908	          githubToken,
909	          gitAuthorEmail,
910	          gitAuthorName,
911	          sshKeyPath,
912	          emit,
913	        });
914	      } catch (e) {
915	        emit({ type: "check_feature_tasks_done_error", workspace: wsRoot, details: String(e) });
916	      }
917	    }
918	  }
919	
920	  // ── Feature Reviewer Daemon (every FEATURE_REVIEW_INTERVAL cycles) ────────
921	  async function featureReviewStep(pulledWorkspaceRoots: string[]): Promise<void> {
922	    for (const wsRoot of pulledWorkspaceRoots) {
923	      try {
924	        const mgmtCoords = parseManagementRepoCoords(wsRoot);
925	        await runFeatureReviewCycle({
926	          workspaceRoot: wsRoot,
927	          baseBranch: mgmtCoords.baseBranch,
928	          mgmtRepoOwner: mgmtCoords.owner,
929	          mgmtRepoName: mgmtCoords.repo,
930	          githubToken,
931	          reviewerGithubToken: process.env.REVIEWER_GITHUB_TOKEN,
932	          gitAuthorEmail,
933	          gitAuthorName,
934	          sshKeyPath,
935	          anthropicApiKey: process.env.ANTHROPIC_API_KEY,
936	          slackWebhookUrl: process.env.SLACK_WEBHOOK_URL,
937	          emit,
938	        });
939	      } catch (e) {
940	        emit({ type: "feature_review_cycle_error", workspace: wsRoot, details: String(e) });
941	      }
942	    }
943	  }
944	
945	  // ── State Invariant Checker (every N cycles) ──────────────────────────────
946	  async function stateInvariantStep(pulledWorkspaceRoots: string[]): Promise<void> {
947	    for (const wsRoot of pulledWorkspaceRoots) {
948	      try {
949	        await runStateInvariantCheck({
950	          workspaceRoot: wsRoot,
951	          githubToken,
952	          gitAuthorEmail,
953	          gitAuthorName,
954	          sshKeyPath,
955	          emit,
956	        });
957	      } catch (e) {
958	        emit({ type: "state_invariant_check_error", workspace: wsRoot, details: String(e) });
959	      }
960	    }
961	  }
962	
963	  // ── Shared reap loop ──────────────────────────────────────────────────────
964	  async function reapStep(
965	    pulledWorkspaceRoots: string[],
966	    currentOutcome: CycleOutcome,
967	  ): Promise<CycleOutcome> {
968	    try {
969	      const reapResult = await runReapLoop({
970	        broker: ports.broker,
971	        workspaceRoots: pulledWorkspaceRoots,
972	        gitAuthorEmail,
973	        gitAuthorName,
974	        sshKeyPath,
975	        githubToken,
976	        emit,
977	        rebaseInFlight,
978	      });
979	      if (reapResult.dispatched > 0) {
980	        if (runtimeProfile === "local-docker") {
981	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
982	        }
983	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
984	        if (currentOutcome === "idle") return "ran_task";
985	      }
986	    } catch (e) {
987	      emit({ type: "reap_loop_error", details: String(e) });
988	    }
989	    return currentOutcome;
990	  }
991	
992	  // ── Poll cycle sequencer ──────────────────────────────────────────────────
993	  async function runOneCycle(): Promise<CycleOutcome> {
994	    const { haltedUrls, failedFeatureBranchMap } = await syncWorkspaces();
995	
996	    let outcome: CycleOutcome = "idle";
997	    let pulledWorkspaceRoots: string[] = [];
998	
999	    // ── Subprocess concurrency guard + task dispatch ────────────────────────
1000	    // In local-subprocess mode all repos share the same container filesystem.
1001	    // Two concurrent subprocesses can race on git checkouts in the same repo.
1002	    // Wrap in a labeled block so we can break out (skipping to reap) when a
1003	    // subprocess is already in-flight.
1004	    dispatchBlock: {
1005	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
1006	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
1007	
1008	      if (runtimeProfile === "local-subprocess") {
1009	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
1010	        if (inFlight >= maxConcurrent) {
1011	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
1012	          break dispatchBlock;
1013	        }
1014	      } else if (runtimeProfile === "local-docker") {
1015	        if (dockerInFlight >= maxConcurrent) {
1016	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
1017	          break dispatchBlock;
1018	        }
1019	      }
1020	
1021	      ({ outcome, pulledWorkspaceRoots } = await claimStep(haltedUrls, failedFeatureBranchMap));
1022	
1023	      if (outcome !== "ran_task") {
1024	        outcome = await fixStep(haltedUrls);
1025	      }
1026	
1027	      if (githubToken && outcome !== "ran_task") {
1028	        outcome = await prPollStep(pulledWorkspaceRoots);
1029	      }
1030	
1031	      if (outcome !== "ran_task") {
1032	        outcome = await reviewerStep(haltedUrls);
1033	      }
1034	    } // end dispatchBlock
1035	
1036	    // ── Feature-Tasks-Done checker ──────────────────────────────────────────
1037	    if (githubToken) {
1038	      await checkFeatureTasksDoneStep(pulledWorkspaceRoots);
1039	    }
1040	
1041	    // ── Feature Done Watcher ────────────────────────────────────────────────
1042	    if (githubToken) {
1043	      await featureDoneStep(pulledWorkspaceRoots);
1044	    }
1045	
1046	    // ── Feature Reviewer Daemon + State Invariant Checker ──────────────────
1047	    cycleCount++;
1048	    if (cycleCount % featureReviewInterval === 0) {
1049	      await featureReviewStep(pulledWorkspaceRoots);
1050	    }
1051	
1052	    if (cycleCount % stateInvariantCheckInterval === 0) {
1053	      await stateInvariantStep(pulledWorkspaceRoots);
1054	    }
1055	
1056	    // ── Shared reap loop ────────────────────────────────────────────────────
1057	    outcome = await reapStep(pulledWorkspaceRoots, outcome);
1058	
1059	    return outcome;
1060	  }
1061	
1062	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
1063	  return 0;
1064	}
1065	
1066	main()
1067	  .then((code) => process.exit(code))
1068	  .catch((e) => {
1069	    try {
1070	      console.log(JSON.stringify({
1071	        type: "fatal_error",
1072	        details: (e as Error).message ?? String(e),
1073	        at: new Date().toISOString(),
1074	      }));
1075	    } catch { /* last resort */ }
1076	    process.exit(4);
1077	  });
