// ── 2. Idempotency: skip non-in_review tasks ──────────────────────────────────

describe("handleMergedPrs — idempotency guard (live branch state)", () => {
  it("skips when live task status is done and workspace_pr is null", async () => {
    // workspace_pr: null means no pending workspace PR — must take the pr_merge_skip path.
    const doneTask = makeTask({ status: "done", workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(doneTask);
    // spawnSync: first call is git show (tryReadTaskFromBranch)
    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowTask(doneTask));

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_skip")).toBe(true);
    const skipEvent = events.find((e) => e.type === "pr_merge_skip");
    expect(String(skipEvent?.reason)).toContain("task_already_done");
    // execSync (git checkout etc.) should not have been called
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
  });

  it("skips when live task status is cancelled", async () => {
    const cancelledTask = makeTask({ status: "cancelled" });
    const wsRoot = makeWorkspaceWithTask(cancelledTask);
    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowTask(cancelledTask));

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_skip")).toBe(true);
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
  });
});

// ── 2b. Already done with pending workspace PR — fast-path ───────────────────

describe("handleMergedPrs — already done with pending workspace PR", () => {
  it("Test A: merges workspace PR when task is already done with workspace_pr open", async () => {
    const doneTask = makeTask({ status: "done", workspace_pr: { url: WORKSPACE_PR_URL, status: "open" } });
    const wsRoot = makeWorkspaceWithTask(doneTask);

    // spawnSync: git show → done task, git merge → success, git push origin → success,
    //   curl merge → success, git push (workspace_pr status write-back) → success
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(doneTask))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())             // git merge --no-edit -X ours origin/feature/test-feature
      .mockReturnValueOnce(mockPushSuccess())            // git push origin (after merge)
      .mockReturnValueOnce(mockCurlMergeSuccess())      // curl PUT merge
      .mockReturnValueOnce(mockPushSuccess());           // git push (workspace_pr status write-back)

    // execSync: git fetch + git checkout + git add (write-back) + git commit (write-back)
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    // workspace_pr_pending_for_done_task event emitted first
    expect(events.some((e) => e.type === "workspace_pr_pending_for_done_task")).toBe(true);
    const pendingEvent = events.find((e) => e.type === "workspace_pr_pending_for_done_task");
    expect(pendingEvent?.workspace_pr_url).toBe(WORKSPACE_PR_URL);

    // workspace_pr_merged event emitted
    expect(events.some((e) => e.type === "workspace_pr_merged")).toBe(true);

    // YAML on disk reflects the write-back: workspace_pr.status = "merged"
    const taskAfter = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;
    expect(taskAfter.status).toBe("done");
    expect(taskAfter.workspace_pr?.status).toBe("merged");
    // Verify no pr_merge_skip was emitted
    expect(events.some((e) => e.type === "pr_merge_skip")).toBe(false);
  });

  it("Test B: skips when task is done and workspace_pr is null", async () => {
    const doneTask = makeTask({ status: "done", workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(doneTask);

    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowTask(doneTask)); // only git show

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_skip")).toBe(true);
    const skipEvent = events.find((e) => e.type === "pr_merge_skip");
    expect(String(skipEvent?.reason)).toContain("task_already_done");
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
  });

  it("Test C: skips when task is done and workspace_pr already merged", async () => {
    const doneTask = makeTask({ status: "done", workspace_pr: { url: WORKSPACE_PR_URL, status: "merged" } });
    const wsRoot = makeWorkspaceWithTask(doneTask);

    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowTask(doneTask)); // only git show

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_skip")).toBe(true);
    const skipEvent = events.find((e) => e.type === "pr_merge_skip");
    expect(String(skipEvent?.reason)).toContain("task_already_done");
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
  });

  it("Test D: emits workspace_pr_merge_failed when merge fails for done task", async () => {
    const doneTask = makeTask({ status: "done", workspace_pr: { url: WORKSPACE_PR_URL, status: "open" } });
    const wsRoot = makeWorkspaceWithTask(doneTask);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(doneTask))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitFailed("CONFLICT"))   // git merge --no-edit -X ours — fails
      .mockReturnValueOnce(mockGitSuccess());            // git merge --abort

    // execSync: git fetch + git checkout succeed
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_pending_for_done_task")).toBe(true);
    expect(events.some((e) => e.type === "workspace_pr_merge_failed")).toBe(true);
    const failedEvent = events.find((e) => e.type === "workspace_pr_merge_failed");
    expect(String(failedEvent?.reason)).toContain("merge_failed");
    // curl merge should NOT have been called
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 3. Skips when feature branch not found ───────────────────────────────────

describe("handleMergedPrs — branch not found", () => {
  it("emits pr_merge_skip with task_branch_not_found when git show fails", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowNotFound())
      .mockReturnValueOnce(mockGitBranchListEmpty()); // branch --list (no local branch)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events[0].type).toBe("pr_merge_skip");
    expect(events[0].reason).toBe("task_branch_not_found");
  });

  it("emits stale_local_branch_pruned before pr_merge_skip when local branch exists", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowNotFound())                          // git show → branch gone on origin
      .mockReturnValueOnce(mockSpawnResult(`  ${TASK_BRANCH}\n`, 0))      // branch --list → local branch found
      .mockReturnValueOnce(mockSpawnResult("", 0));                        // branch -D → delete succeeds

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    const pruneEvent = events.find((e) => e.type === "stale_local_branch_pruned");
    expect(pruneEvent).toBeDefined();
    expect(pruneEvent!.branch).toBe(TASK_BRANCH);
    expect(pruneEvent!.task_id).toBe(TASK_ID);
    expect(pruneEvent!.feature_id).toBe(FEATURE_ID);

    // pr_merge_skip still fires after the prune
    const skipEvent = events.find((e) => e.type === "pr_merge_skip");
    expect(skipEvent).toBeDefined();
    expect(skipEvent!.reason).toBe("task_branch_not_found");

    // prune must precede skip
    expect(events.indexOf(pruneEvent!)).toBeLessThan(events.indexOf(skipEvent!));
  });
});

// ── 4. Happy path: marks done, merges workspace PR ───────────────────────────

describe("handleMergedPrs — happy path", () => {
  it("marks task done, updates pr.status to merged, appends log entry, merges workspace PR", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    // spawnSync calls: git show, git rebase --abort, git push (YAML commit), git merge,
    //   git push origin, curl, git push (workspace_pr status write-back)
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())        // git push (YAML commit)
      .mockReturnValueOnce(mockGitSuccess())         // git merge --no-edit -X ours origin/feature/test-feature
      .mockReturnValueOnce(mockPushSuccess())        // git push origin (after merge)
      .mockReturnValueOnce(mockCurlMergeSuccess())  // curl PUT merge
      .mockReturnValueOnce(mockPushSuccess());       // git push (workspace_pr status write-back)

    // execSync calls: git fetch, git checkout, git pull, git add, git commit, git fetch (rebase),
    //   git add (write-back), git commit (write-back)
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    // Verify task YAML was updated on disk.
    const updatedTask = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;

    expect(updatedTask.status).toBe("done");
    expect(updatedTask.pr.status).toBe("merged");
    expect(updatedTask.workspace_pr?.status).toBe("merged");
    expect(updatedTask.log.some((e) => e.action === "done")).toBe(true);
    const doneEntry = updatedTask.log.find((e) => e.action === "done");
    expect(doneEntry?.note).toBe("Implementation PR merged — automated close-out by pr-merge loop.");
    expect(doneEntry?.by).toBe(GIT_AUTHOR_EMAIL);

    // Verify events.
    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "workspace_pr_merged")).toBe(true);
  });

  it("calls git fetch, checkout, pull in correct order", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git merge --no-edit -X ours origin/feature/test-feature
      .mockReturnValueOnce(mockPushSuccess())        // git push origin (after merge)
      .mockReturnValueOnce(mockCurlMergeSuccess())  // curl PUT merge
      .mockReturnValueOnce(mockPushSuccess());       // git push (workspace_pr status write-back)
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
    }));

    const execCalls = vi.mocked(execSync).mock.calls.map((c) => String(c[0]));
    expect(execCalls.some((c) => c.includes("fetch origin"))).toBe(true);
    expect(execCalls.some((c) => c.includes(`checkout "${TASK_BRANCH}"`))).toBe(true);
    expect(execCalls.some((c) => c.includes(`pull --rebase origin "${TASK_BRANCH}"`))).toBe(true);
  });

  it("uses the correct PUT URL for workspace PR merge", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())         // git merge --no-edit -X ours origin/feature/test-feature
      .mockReturnValueOnce(mockPushSuccess())        // git push origin (after merge)
      .mockReturnValueOnce(mockCurlMergeSuccess())  // curl PUT merge
      .mockReturnValueOnce(mockPushSuccess());       // git push (workspace_pr status write-back)
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
    }));

    const curlCall = vi.mocked(spawnSync).mock.calls.find(
      ([cmd]) => cmd === "curl",
    );
    expect(curlCall).toBeDefined();
    const curlArgs = curlCall![1] as string[];
    const url = curlArgs[curlArgs.length - 1];
    expect(url).toContain(`/repos/${MGMT_OWNER}/${MGMT_REPO}/pulls/55/merge`);
  });
});

// ── 4b. notifier called on done ───────────────────────────────────────────────

describe("handleMergedPrs — notifier", () => {
  it("calls notifier.notify with type=done after task_marked_done", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockCurlMergeSuccess())
      .mockReturnValueOnce(mockPushSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const notified: Array<{ type: string; taskId: string; featureId: string; taskTitle?: string; prUrl?: string }> = [];
    const notifier = { notify: async (e: { type: string; taskId: string; featureId: string; taskTitle?: string; prUrl?: string }) => { notified.push(e); } };

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      notifier,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(notified).toHaveLength(1);
    expect(notified[0].type).toBe("done");
    expect(notified[0].taskId).toBe(TASK_ID);
    expect(notified[0].featureId).toBe(FEATURE_ID);
    expect(events.some((e) => e.type === "task_notification_failed")).toBe(false);
  });

  it("emits task_notification_failed when notifier throws; merge still proceeds", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockCurlMergeSuccess())
      .mockReturnValueOnce(mockPushSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const failingNotifier = { notify: async () => { throw new Error("slack timeout"); } };
    const events: Record<string, unknown>[] = [];

    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      notifier: failingNotifier,
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "task_notification_failed" && e.event === "done")).toBe(true);
    // Workspace PR merge still proceeds even when notifier throws.
    expect(events.some((e) => e.type === "workspace_pr_merged")).toBe(true);
  });

  it("does not invoke notifier when notifier is absent", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess())
      .mockReturnValueOnce(mockCurlMergeSuccess())
      .mockReturnValueOnce(mockPushSuccess());
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];

    await expect(handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      // notifier intentionally omitted
      emit: (e) => events.push(e),
    }))).resolves.toBeUndefined();

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "task_notification_failed")).toBe(false);
  });
});

