// ── 13. Orphaned-branch recovery (branch deleted after manual workspace-PR merge) ─

describe("handleMergedPrs — orphaned branch recovery", () => {
  it("skips entirely when task is already done on the feature branch", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);
    const doneTask = { ...task, status: "done" as const };

    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      // Task branch is missing on origin
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) throw new Error("fatal: remote ref not found");
      return undefined as unknown as Buffer;
    });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))     // tryReadTaskFromBranch — task branch (in_review, passes guard)
      .mockReturnValueOnce(mockGitSuccess())           // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockGitShowTask(doneTask)); // tryReadTaskFromBranch — feature branch (already done)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, branchMissing: true })],
      emit: (e) => events.push(e),
    }));

    const skipEvent = events.find((e) => e.type === "pr_merge_skip");
    expect(skipEvent).toBeDefined();
    expect(skipEvent?.reason).toBe("task_already_done_on_feature_branch");
    expect(events.some((e) => e.type === "pr_merge_branch_recreated")).toBe(false);
    expect(events.some((e) => e.type === "task_marked_done")).toBe(false);
  });

  it("recreates from feature branch when task is not yet done there, marks done, skips workspace PR merge", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      // Task branch is missing on origin; all other execSync calls succeed
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) throw new Error("fatal: remote ref not found");
      return undefined as unknown as Buffer;
    });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch — task branch (in_review, passes guard)
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockGitShowTask(task))    // tryReadTaskFromBranch — feature branch (in_review, not done → use as base)
      .mockReturnValueOnce(mockPushSuccess());       // git push (done-state commit)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, branchMissing: true })],
      emit: (e) => events.push(e),
    }));

    const recreatedEvent = events.find((e) => e.type === "pr_merge_branch_recreated");
    expect(recreatedEvent).toBeDefined();
    expect(recreatedEvent?.base).toBe(`feature/${FEATURE_ID}`);
    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    // workspace PR merge is skipped — branch was recreated (workspace PR already merged)
    expect(events.some((e) => e.type === "workspace_pr_already_merged")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);

    // YAML on disk should be done with workspace_pr.status = "merged"
    const updatedTask = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;
    expect(updatedTask.status).toBe("done");
    expect(updatedTask.workspace_pr?.status).toBe("merged");
    expect(updatedTask.log.find((e) => e.action === "done")?.note).toContain("orphaned-branch recovery");
  });

  it("falls back to mgmtBaseBranch when feature branch is also absent", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) throw new Error("fatal: remote ref not found");
      return undefined as unknown as Buffer;
    });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch — task branch (in_review)
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockGitShowNotFound())    // tryReadTaskFromBranch — feature branch (absent → fall back to main)
      .mockReturnValueOnce(mockPushSuccess());       // git push (done-state commit)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, branchMissing: true })],
      emit: (e) => events.push(e),
    }));

    const recreatedEvent = events.find((e) => e.type === "pr_merge_branch_recreated");
    expect(recreatedEvent).toBeDefined();
    expect(recreatedEvent?.base).toBe("main");
    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
  });

  it("emits pr_merge_done_blocked when branch recreation itself fails", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) throw new Error("fatal: remote ref not found");
      if (c.includes("checkout -B")) throw new Error("fatal: checkout failed");
      return undefined as unknown as Buffer;
    });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))   // tryReadTaskFromBranch — task branch
      .mockReturnValueOnce(mockGitSuccess())         // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockGitShowNotFound())    // tryReadTaskFromBranch — feature branch (not found → proceed to recreate)
      .mockReturnValueOnce(mockGitSuccess());        // git rebase --abort (cleanup after failed checkout)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_done_blocked")).toBe(true);
    const blocked = events.find((e) => e.type === "pr_merge_done_blocked");
    expect(blocked?.reason).toBe("branch_sync_failed");
  });
});

